def write_batch(ids):
    n = 0
    for cid in ids:
        assert cid in P, cid
        txt, basis, conf, trig = P[cid]
        obj = {"case_id": cid, "prediction_text": txt, "basis": basis, "confidence": conf, "trigger": trig}
        (ROOT / (cid + ".json")).write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
        n += 1
    return n

if __name__ == "__main__":
    assert len(B21) == 20 and len(B22) == 20 and len(set(B21 + B22)) == 40
    n1 = write_batch(B21); assert n1 == 20, n1
    n2 = write_batch(B22); assert n2 == 20, n2
    # verify by exact id list only
    tot_bytes = 0; cm = ru = di = 0
    for cid in B21 + B22:
        p = ROOT / (cid + ".json")
        raw = p.read_bytes(); tot_bytes += len(raw)
        o = json.loads(raw.decode("utf-8"))
        assert o["case_id"] == cid and all(k in o for k in ("prediction_text","basis","confidence","trigger"))
        assert all(k in o["trigger"] for k in ("changed_main","reserve_used","disputed","reason"))
        cm += bool(o["trigger"]["changed_main"]); ru += bool(o["trigger"]["reserve_used"]); di += bool(o["trigger"]["disputed"])
    print(f"OK total=40 b21={n1} b22={n2} bytes={tot_bytes} changed_main={cm} reserve_used={ru} disputed={di}")
